        thread2.start();
    }

    static void Thread1() {
        do {
            thread1WantsToEnter = true;
            while (thread2WantsToEnter) {
                if (favouredThread == 2) {
                    thread1WantsToEnter = false;
                    while (favouredThread == 2);
                    thread1WantsToEnter = true;
                }
            }
            favouredThread = 2;
            thread1WantsToEnter = false;
        } while (!completed);
    }

    static void Thread2() {
        do {
